CREATE TABLE el_support_tickets(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,number TEXT NOT NULL,student_id TEXT,created_by TEXT NOT NULL,assigned_to TEXT,category TEXT NOT NULL CHECK(category IN ('academic','financial','registration','teacher_complaint','technical','general')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','waiting','resolved','closed')),resolved_at INTEGER,rating INTEGER CHECK(rating BETWEEN 1 AND 5),rating_note TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(org_id,id),UNIQUE(org_id,number),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,assigned_to) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_ticket_messages(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,ticket_id TEXT NOT NULL,user_id TEXT NOT NULL,body TEXT NOT NULL,internal INTEGER NOT NULL DEFAULT 0 CHECK(internal IN (0,1)),is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,FOREIGN KEY(org_id,ticket_id) REFERENCES el_support_tickets(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_tickets_branch ON el_support_tickets(org_id,branch_id,status,updated_at);
CREATE INDEX el_tickets_requester ON el_support_tickets(org_id,created_by,updated_at);
CREATE INDEX el_ticket_messages_lookup ON el_ticket_messages(org_id,ticket_id,created_at);
CREATE TRIGGER el_ticket_owner_lock BEFORE UPDATE ON el_support_tickets BEGIN SELECT CASE WHEN NEW.created_by<>OLD.created_by OR NEW.student_id IS NOT OLD.student_id OR NEW.branch_id<>OLD.branch_id OR NEW.body<>OLD.body OR NEW.subject<>OLD.subject THEN RAISE(ABORT,'Support ticket identity is immutable') END;END;
CREATE TABLE el_documents(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,target_kind TEXT NOT NULL CHECK(target_kind IN ('student','teacher','employee','group','ticket','organization','finance')),target_id TEXT NOT NULL,title TEXT NOT NULL,category TEXT NOT NULL,shared_portal INTEGER NOT NULL DEFAULT 0 CHECK(shared_portal IN (0,1)),expires_on TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_by TEXT NOT NULL,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE TABLE el_document_versions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,document_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),filename TEXT NOT NULL,mime TEXT NOT NULL CHECK(mime IN ('application/pdf','image/png','image/jpeg')),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 1 AND 131072),sha256 TEXT NOT NULL,iv TEXT NOT NULL,ciphertext TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(document_id,version),FOREIGN KEY(org_id,document_id) REFERENCES el_documents(org_id,id),FOREIGN KEY(org_id,created_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_documents_target ON el_documents(org_id,target_kind,target_id,status);
CREATE INDEX el_documents_branch ON el_documents(org_id,branch_id,status,expires_on,title);
CREATE INDEX el_document_versions_lookup ON el_document_versions(org_id,document_id,version DESC);
CREATE TRIGGER el_document_version_immutable BEFORE UPDATE ON el_document_versions BEGIN SELECT RAISE(ABORT,'Document versions are immutable');END;
CREATE TRIGGER el_document_version_no_delete BEFORE DELETE ON el_document_versions WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Document versions cannot be deleted');END;
CREATE TRIGGER el_document_capacity BEFORE INSERT ON el_documents WHEN (SELECT count(*) FROM el_documents WHERE org_id=NEW.org_id)>=1000 BEGIN SELECT RAISE(ABORT,'Document store capacity exceeded');END;
CREATE TRIGGER el_document_version_capacity BEFORE INSERT ON el_document_versions WHEN NEW.version>20 OR (SELECT count(*) FROM el_document_versions WHERE document_id=NEW.document_id)>=20 BEGIN SELECT RAISE(ABORT,'Document version capacity exceeded');END;
